import{_ as e,o as n,c as o,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng & Đề xuất Cộng tác viên (AI Features)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/06-ai-features.md","filePath":"ba/06-ai-features.md"}'),d={name:"ba/06-ai-features.md"};function i(r,t,h,g,a,l){return n(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_06-—-he-sinh-thai-tinh-nang-ai-đo-thi-tri-thuc-xu-huong-đe-xuat-cong-tac-vien-ai-features" tabindex="-1">06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng &amp; Đề xuất Cộng tác viên (AI Features) <a class="header-anchor" href="#_06-—-he-sinh-thai-tinh-nang-ai-đo-thi-tri-thuc-xu-huong-đe-xuat-cong-tac-vien-ai-features" aria-label="Permalink to &quot;06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng &amp; Đề xuất Cộng tác viên (AI Features)&quot;">​</a></h1><p>&gt; [&lt;&lt; 05 - Content &amp; Task Workflow](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/05-content-task-workflow.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 07 - Publishing &amp; Social &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/07-publishing-social-collaborator.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.7 AI Features</code> — 19 FR (<code>3.7.1</code> – <code>3.7.19</code>)</strong> | <code>UC-088</code> – <code>UC-106</code>. &gt; Đã loại bỏ hoàn toàn tính năng sinh kịch bản Livestream (<code>Generate Livestream Script</code>) theo <code>AGENTS.md</code> và đồng bộ 100% với kiến trúc <strong>RAG Brand Knowledge</strong>, <strong>Neo4j Trend Knowledge Graph</strong>, <strong>AI Video Studio</strong>, <strong>Collaborator Directory &amp; AI Recommendation</strong>, cùng cơ chế <strong>4 Nhóm Tác vụ AI Tính phí vs. Tác vụ Miễn phí (<code>workspace-credit-unification</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-19-yeu-cau-chuc-nang-chuan-3-7-1-–-3-7-19" tabindex="-1">1. Bảng Tổng hợp 19 Yêu cầu Chức năng Chuẩn (<code>3.7.1</code> – <code>3.7.19</code>) <a class="header-anchor" href="#_1-bang-tong-hop-19-yeu-cau-chuc-nang-chuan-3-7-1-–-3-7-19" aria-label="Permalink to &quot;1. Bảng Tổng hợp 19 Yêu cầu Chức năng Chuẩn (`3.7.1` – `3.7.19`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:center;">Phân loại Credit</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.7.1</code></strong></td><td style="text-align:center;"><code>UC-088</code></td><td style="text-align:left;"><strong>View Trending Topics Suggestions</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem danh sách chủ đề xu hướng nóng đa nền tảng (TikTok, Facebook, Instagram, YouTube, Google News) được cá nhân hóa theo lĩnh vực của Workspace.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.2</code></strong></td><td style="text-align:center;"><code>UC-089</code></td><td style="text-align:left;"><strong>View AI Trend Knowledge Graph</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Khám phá trực quan Đồ thị Tri thức Xu hướng (<code>Neo4j Knowledge Graph</code>) thể hiện mối liên hệ giữa Chủ đề (<code>Topic</code>), Từ khóa (<code>Keyword</code>), Hashtag, Thực thể thương hiệu và Ý tưởng nội dung.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.3</code></strong></td><td style="text-align:center;"><code>UC-090</code></td><td style="text-align:left;"><strong>View Brand Knowledge Documents</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem danh sách các tài liệu tri thức thương hiệu (<code>Brand Knowledge Documents</code>) đã nạp vào kho RAG của Workspace cùng trạng thái băm vector (<code>INDEXED</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.4</code></strong></td><td style="text-align:center;"><code>UC-091</code></td><td style="text-align:left;"><strong>Upload Brand Knowledge Document</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Tải lên tài liệu nhận diện thương hiệu, hồ sơ sản phẩm, cẩm nang giọng văn (PDF, DOCX, TXT, MD) để <code>brandhub-ai-service</code> phân mảnh và tạo vector embedding làm ngữ cảnh RAG.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.5</code></strong></td><td style="text-align:center;"><code>UC-092</code></td><td style="text-align:left;"><strong>Delete Brand Knowledge Document</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xóa tài liệu tri thức thương hiệu khỏi Workspace và gỡ bỏ các đoạn vector embedding tương ứng.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.6</code></strong></td><td style="text-align:center;"><code>UC-093</code></td><td style="text-align:left;"><strong>Generate Caption</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>CONTENT_GENERATE</code>)</td><td style="text-align:left;">Sinh nội dung bài viết / caption đa nền tảng kết hợp ngữ cảnh thương hiệu (RAG) và xu hướng Neo4j; hỗ trợ tinh chỉnh biến thể (<code>CAPTION_VARIANTS</code> — miễn phí) và làm mượt văn phong tự nhiên (<code>Content Humanizer</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.7</code></strong></td><td style="text-align:center;"><code>UC-094</code></td><td style="text-align:left;"><strong>Generate Ambassador</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>AMBASSADOR_GENERATE</code>)</td><td style="text-align:left;">Khởi tạo hình mẫu Đại sứ Thương hiệu ảo bằng AI (<code>Virtual Brand Ambassador</code> — ngoại hình, phong cách, trang phục, bối cảnh) và sinh bảng góc mặt nhân vật (<code>CHARACTER_SHEET</code> — miễn phí).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.8</code></strong></td><td style="text-align:center;"><code>UC-095</code></td><td style="text-align:left;"><strong>View Image Style Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Duyệt thư viện mẫu phong cách hình ảnh thương mại (<code>Commercial Image Presets</code> — Studio, Lifestyle, Minimalist, Luxury, Cyber, Seasonal...).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.9</code></strong></td><td style="text-align:center;"><code>UC-096</code></td><td style="text-align:left;"><strong>Generate Image</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>COMMERCIAL_IMAGE</code>)</td><td style="text-align:left;">Sinh ảnh quảng cáo thương mại / ảnh sản phẩm chất lượng cao bằng AI theo prompt, mẫu phong cách (<code>3.7.8</code>) hoặc ghép cùng Đại sứ thương hiệu (<code>3.7.7</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.10</code></strong></td><td style="text-align:center;"><code>UC-097</code></td><td style="text-align:left;"><strong>View Video Style Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Duyệt thư viện mẫu phong cách, bố cục chuyển cảnh và tỷ lệ khung hình (<code>9:16</code>, <code>16:9</code>, <code>1:1</code>) cho video ngắn / video sản phẩm.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.11</code></strong></td><td style="text-align:center;"><code>UC-098</code></td><td style="text-align:left;"><strong>Generate Video</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>VIDEO_GENERATE</code>)</td><td style="text-align:left;">Sinh video ngắn / video quảng cáo sản phẩm bằng AI (<code>AI Video Studio</code> / <code>Product Video</code> / <code>Video Space</code>) theo kịch bản, hình ảnh đầu vào và mẫu phong cách (<code>3.7.10</code>), xử lý bất đồng bộ kèm hoàn trả credit nếu lỗi.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.12</code></strong></td><td style="text-align:center;"><code>UC-099</code></td><td style="text-align:left;"><strong>Export File</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xuất nội dung AI đã tạo hoặc lưu trực tiếp hình ảnh/video/văn bản về thiết bị hoặc đẩy thẳng vào <code>Material Library</code> / phần <code>TaskSection</code> của công việc đang mở.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.13</code></strong></td><td style="text-align:center;"><code>UC-100</code></td><td style="text-align:left;"><strong>Crawl Schedule Config</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;">Hệ thống</td><td style="text-align:left;">Cấu hình lịch trình thu thập dữ liệu xu hướng tự động (<code>Crawler Cron Schedule</code>), nguồn thu thập đa nền tảng và kích hoạt chạy đường ống xu hướng tức thì (<code>Run Pipeline Now</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.14</code></strong></td><td style="text-align:center;"><code>UC-101</code></td><td style="text-align:left;"><strong>Suggest Hashtag Trend</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí (<code>HASHTAG_GENERATE</code>)</td><td style="text-align:left;">Gợi ý bộ Hashtag theo ngữ cảnh nội dung bài viết kết hợp dữ liệu xu hướng thực tế trong Workspace.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.15</code></strong></td><td style="text-align:center;"><code>UC-102</code></td><td style="text-align:left;"><strong>View Collaborator Directory</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem danh bạ đối tác / KOL / KOC / Influencer / Freelancer (<code>Collaborator Directory</code>) của Agency kèm bộ lọc theo lĩnh vực, nền tảng, lượng người theo dõi và mức giá tham khảo.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.16</code></strong></td><td style="text-align:center;"><code>UC-103</code></td><td style="text-align:left;"><strong>Create Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Thêm mới hồ sơ đối tác / KOL vào danh bạ của Agency (Tên, Lĩnh vực, Kênh MXH, Lượng follower, Tỷ lệ tương tác, Đơn giá tham khảo, Thông tin liên hệ).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.17</code></strong></td><td style="text-align:center;"><code>UC-104</code></td><td style="text-align:left;"><strong>Update Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Cập nhật thông tin hồ sơ, chỉ số tương tác hoặc ghi chú hợp tác của KOL/Cộng tác viên trong danh bạ.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.18</code></strong></td><td style="text-align:center;"><code>UC-105</code></td><td style="text-align:left;"><strong>Remove Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xóa hồ sơ KOL/Cộng tác viên khỏi danh bạ của Agency.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.19</code></strong></td><td style="text-align:center;"><code>UC-106</code></td><td style="text-align:left;"><strong>Recommend Collaborator</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Hệ thống AI phân tích mục tiêu chiến dịch, ngành hàng, ngân sách và đối tượng mục tiêu để đề xuất danh sách KOL/Cộng tác viên phù hợp nhất kèm điểm tương thích (<code>Match Score</code>) và lý do đề xuất.</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-chi-tiet-tung-nhom-tinh-nang-ai" tabindex="-1">2. Đặc tả Nghiệp vụ Chi tiết Từng Nhóm Tính năng AI <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-chi-tiet-tung-nhom-tinh-nang-ai" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Chi tiết Từng Nhóm Tính năng AI&quot;">​</a></h2><h3 id="_2-1-kham-pha-xu-huong-đo-thi-tri-thuc-3-7-1-3-7-2-3-7-13-3-7-14" tabindex="-1">2.1. Khám phá Xu hướng &amp; Đồ thị Tri thức (<code>3.7.1</code>, <code>3.7.2</code>, <code>3.7.13</code>, <code>3.7.14</code>) <a class="header-anchor" href="#_2-1-kham-pha-xu-huong-đo-thi-tri-thuc-3-7-1-3-7-2-3-7-13-3-7-14" aria-label="Permalink to &quot;2.1. Khám phá Xu hướng &amp; Đồ thị Tri thức (`3.7.1`, `3.7.2`, `3.7.13`, `3.7.14`)&quot;">​</a></h3><ul><li><strong>Đường ống thu thập đa nền tảng (<code>3.7.13 Crawl Schedule Config</code>)</strong>: <ul><li>Do <code>Admin</code> quản lý tại <code>/admin/crawler</code>. Hệ thống thu thập xu hướng theo lịch định kỳ hoặc kích hoạt chạy ngay (<code>Run Pipeline Now</code>), trích xuất chủ đề, từ khóa, cảm xúc (<code>sentiment</code>) và lưu trữ vào <strong>Neo4j Knowledge Graph</strong> cùng MongoDB.</li></ul></li><li><strong>Trình khám phá xu hướng trong Workspace (<code>3.7.1</code> &amp; <code>3.7.2</code>)</strong>: <ul><li>Tại <code>/workspaces/:id/trends</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code> (kể cả trong chế độ <code>PERSONAL</code>) xem được các xu hướng mới nhất, bấm vào từng nút trên <strong>Đồ thị Tri thức (<code>AI Trend Knowledge Graph</code>)</strong> để xem các góc tiếp cận nội dung (<code>content angles</code>) và chuyển hóa ngay 1 chạm thành bài đăng hoặc kịch bản video.</li></ul></li><li><strong>Gợi ý Hashtag thông minh (<code>3.7.14 Suggest Hashtag Trend</code>)</strong>: <ul><li>Ngay trong trình soạn thảo <code>POST.CAPTION</code> / <code>VIDEO.CAPTION</code>, người dùng bấm gợi ý Hashtag theo nội dung đang viết. Tác vụ này thuộc nhóm <code>HASHTAG_GENERATE</code> (<strong>hoàn toàn miễn phí credit</strong>, <code>unit_credits = 0</code>).</li></ul></li></ul><h3 id="_2-2-kho-tri-thuc-thuong-hieu-rag-3-7-3-–-3-7-5" tabindex="-1">2.2. Kho Tri thức Thương hiệu RAG (<code>3.7.3</code> – <code>3.7.5</code>) <a class="header-anchor" href="#_2-2-kho-tri-thuc-thuong-hieu-rag-3-7-3-–-3-7-5" aria-label="Permalink to &quot;2.2. Kho Tri thức Thương hiệu RAG (`3.7.3` – `3.7.5`)&quot;">​</a></h3><ul><li>Cho phép mỗi Workspace (cả <code>AGENCY</code> lẫn <code>PERSONAL</code>) xây dựng bộ nhớ dài hạn cho AI: <ul><li>Khi người dùng tải lên tài liệu hướng dẫn thương hiệu, thông số sản phẩm hoặc đề cương bài tập lớn (<code>3.7.4 Upload Brand Knowledge Document</code>), <code>brandhub-ai-service</code> trích xuất văn bản, chia nhỏ (<code>chunking</code>) và lập chỉ mục vector.</li><li>Khi gọi <code>3.7.6 Generate Caption</code>, hệ thống tự động truy xuất các đoạn tri thức liên quan nhất (<code>RAG retrieval</code>) kết hợp với ngữ cảnh xu hướng Neo4j để sinh bài viết bám sát thông tin thật, không bịa đặt thông số sản phẩm.</li></ul></li></ul><h3 id="_2-3-studio-sang-tao-noi-dung-đa-phuong-thuc-3-7-6-–-3-7-12" tabindex="-1">2.3. Studio Sáng tạo Nội dung Đa phương thức (<code>3.7.6</code> – <code>3.7.12</code>) <a class="header-anchor" href="#_2-3-studio-sang-tao-noi-dung-đa-phuong-thuc-3-7-6-–-3-7-12" aria-label="Permalink to &quot;2.3. Studio Sáng tạo Nội dung Đa phương thức (`3.7.6` – `3.7.12`)&quot;">​</a></h3><ol><li><strong>Sinh Bài viết &amp; Tinh chỉnh Văn phong (<code>3.7.6 Generate Caption</code>)</strong>: <ul><li>Người dùng chọn nền tảng mục tiêu (<strong>Facebook, Instagram, TikTok, Threads</strong>), giọng văn (<code>Tone of Voice</code>), độ dài và từ khóa.</li><li>Tác vụ sinh bài mới tính phí theo mã <code>CONTENT_GENERATE</code>. Các bước tạo biến thể / rút gọn / mở rộng / làm tự nhiên văn phong (<code>CAPTION_VARIANTS</code> / <code>Content Humanizer</code>) được miễn phí credit.</li><li>Nội dung sinh ra tự động đi qua bộ lọc an toàn (<code>Caption Text Moderation</code> / <code>3.6.33</code>) trước khi hiển thị.</li></ul></li><li><strong>Đại sứ Thương hiệu Ảo &amp; Ảnh Thương mại (<code>3.7.7</code>, <code>3.7.8</code>, <code>3.7.9</code>)</strong>: <ul><li>Tạo nhân vật đại sứ thương hiệu nhất quán (<code>AMBASSADOR_GENERATE</code> — tính phí; sinh bảng góc mặt <code>CHARACTER_SHEET</code> — miễn phí).</li><li>Chọn mẫu phong cách ảnh thương mại (<code>3.7.8 View Image Style Template</code>) và sinh ảnh sản phẩm/quảng cáo (<code>3.7.9 Generate Image</code> — mã giá <code>COMMERCIAL_IMAGE</code>).</li></ul></li><li><strong>Studio Video AI (<code>3.7.10</code>, <code>3.7.11</code>, <code>3.7.12</code>)</strong>: <ul><li>Hỗ trợ xem mẫu phong cách video (<code>3.7.10</code>) và tạo video bằng AI (<code>3.7.11 Generate Video</code> — mã giá <code>VIDEO_GENERATE</code>) trong các không gian chuyên biệt: <strong>AI Video Studio</strong>, <strong>Product Video Studio</strong> và <strong>Video Space</strong>.</li><li>Vì quá trình dựng video AI chạy bất đồng bộ (asynchronous job), hệ thống thực hiện <strong>tạm giữ credit (<code>HOLD</code> / <code>Reserve</code>)</strong> khi bắt đầu job; chỉ khi video hoàn tất thành công mới thực hiện <strong>khấu trừ thật (<code>SETTLE</code> / <code>Commit</code>)</strong>; nếu provider lỗi hoặc timeout, hệ thống tự động <strong>hoàn trả toàn bộ số credit tạm giữ (<code>RELEASE</code>)</strong>.</li></ul></li></ol><h3 id="_2-4-danh-ba-cong-tac-vien-kol-đe-xuat-bang-ai-3-7-15-–-3-7-19" tabindex="-1">2.4. Danh bạ Cộng tác viên / KOL &amp; Đề xuất bằng AI (<code>3.7.15</code> – <code>3.7.19</code>) <a class="header-anchor" href="#_2-4-danh-ba-cong-tac-vien-kol-đe-xuat-bang-ai-3-7-15-–-3-7-19" aria-label="Permalink to &quot;2.4. Danh bạ Cộng tác viên / KOL &amp; Đề xuất bằng AI (`3.7.15` – `3.7.19`)&quot;">​</a></h3><ul><li>Phục vụ trực tiếp cho việc lập kế hoạch truyền thông và thực thi loại công việc <strong><code>KOL_BOOKING</code></strong>: <ul><li><code>Owner</code> và <code>Manager</code> quản lý danh bạ đối tác/KOL (<code>3.7.15</code>–<code>3.7.18</code>).</li><li>Khi cần chọn KOL cho chiến dịch hoặc công việc <code>KOL_BOOKING</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code> gọi <strong><code>3.7.19 Recommend Collaborator</code></strong>: AI đối chiếu thông tin chiến dịch với hồ sơ trong danh bạ để xếp hạng các KOL phù hợp nhất và điền nhanh vào phần <code>KOL.SHORTLIST</code>.</li></ul></li></ul><hr><h2 id="_3-co-che-tru-ai-credit-trong-che-đo-agency-va-personal" tabindex="-1">3. Cơ chế Trừ AI Credit trong Chế độ <code>AGENCY</code> và <code>PERSONAL</code> <a class="header-anchor" href="#_3-co-che-tru-ai-credit-trong-che-đo-agency-va-personal" aria-label="Permalink to &quot;3. Cơ chế Trừ AI Credit trong Chế độ `AGENCY` và `PERSONAL`&quot;">​</a></h2><p>Theo kiến trúc hợp nhất tại <code>docs/feature/workspace-credit-unification/spec.md</code>:</p><ol><li><strong>Nguồn tiền duy nhất (<code>Single Funding Source</code>)</strong>: Mọi chi phí AI đều được trừ từ ví <code>agency_credit_wallets</code> của <code>Agency</code> (hoặc của <code>Personal Hub Agency</code> khi ở chế độ <code>PERSONAL</code>), ưu tiên trừ <strong>Plan Credit (credit theo chu kỳ gói)</strong> trước rồi mới trừ <strong>Purchased Credit (credit mua thêm không hết hạn)</strong>.</li><li><strong>Trần ngân sách cấp Workspace (<code>Workspace Credit Cap</code>)</strong>: <ul><li><code>Owner</code> có thể đặt hạn mức <code>workspaceLimit</code> cho từng Workspace (hoặc để <code>NULL</code> = dùng tự do theo số dư ví tổng; <code>0</code> = khóa các tác vụ AI tính phí).</li><li>Cả <code>Owner</code>, <code>Manager</code> và <code>Creator</code> khi dùng AI trong một Workspace đều tiêu thụ ngân sách của Workspace đó.</li></ul></li><li><strong>4 Nhóm Tác vụ Tính phí Duy nhất</strong>: <ul><li>Chỉ đúng 4 nhóm <code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code> mới trừ credit theo bảng giá cố định của <code>Admin</code>. Mọi thao tác AI hỗ trợ khác đều miễn phí (<code>unit_credits = 0</code>).</li></ul></li></ol>',19)])])}const p=e(d,[["render",i]]);export{u as __pageData,p as default};
